import type { ApplicationUser } from './application-user-model';
import type { InspectionResponse } from './inspection-response-model';

export interface Comment {
  /**
   * @displayName Comment ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Comment Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  commentName: string;
  /**
   * @displayName Comment Text
   * @validationRule Required for create/update operations
   */
  commentText: string;
  /**
   * @displayName Created By
   * @validationRule Required for create/update operations
   */
  createdBy: Pick<ApplicationUser, 'id' | 'applicationUserName'>;
  /**
   * @displayName Created Date
   * @validationRule Required for create/update operations
   */
  createdDate: string;
  /**
   * @displayName Inspection Response
   * @validationRule Required for create/update operations
   */
  inspectionResponse: Pick<InspectionResponse, 'id' | 'inspectionResponseName'>;
}

export const _Comment = 'Comment' as const;